# qx2_rle_enc :: 'AAAABBBCCDAA'
def qx2_rle_enc(s):
    if not s:
        return []
    out = []
    cur, n = s[0], 1
    for c in s[1:]:
        if c == cur:
            n += 1
        else:
            out.append((cur, n))
            cur, n = c, 1
    out.append((cur, n))
    return out

if __name__ == '__main__':
    print(qx2_rle_enc('AAAABBBCCDAA'))

